export type StorageKey = 'fridge' | 'pantry' | 'freezer';
export type CategoryKey =
    | 'fruits'
    | 'vegetables'
    | 'dairy'
    | 'meat'
    | 'seafood'
    | 'grains'
    | 'legumes'
    | 'sweets'
    | 'frozen'
    | 'beverages'
    | 'other';
export const CATEGORIES: CategoryKey[] = [
    'fruits',
    'vegetables',
    'dairy',
    'meat',
    'seafood',
    'grains',
    'legumes',
    'sweets',
    'frozen',
    'beverages',
    'other',
];
export const STORAGE_TYPES: StorageKey[] = ['fridge', 'pantry', 'freezer'];

export interface NutritionalInfo {
    calories?: number;
    protein?: number;
    carbs?: number;
    fat?: number;
}
export interface Product {
    id: string;
    name: string;
    quantity: number;
    expiryDate: Date | null;
    storage: StorageKey;
    category: CategoryKey;
    barcode?: string;
    estimatedPrice?: number;
    nutritionalInfo?: NutritionalInfo;
}

export interface ShoppingItem {
    id: string;
    name: string;
    quantity: number;
    expiryDate: Date | null;
    category: CategoryKey;
    barcode?: string;
    estimatedPrice?: number;
}

export interface ScannedItem {
    id: string;
    name: string;
    barcode: string;
    nutritionalInfo?: NutritionalInfo;
}

export type NotificationType = 'expiry' | 'low_stock' | 'other';

export interface Notification {
    id: string;
    type: NotificationType;
    message: string;
    timestamp: Date;
    read: boolean;
    productId?: string;
}

export interface Recipe {
    id: string;
    name: string;
    ingredients: string[];
    instructions: string[];
}
